import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# HIP kernel for fused amax computation and FP8 quantization
fp8_quantize_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

// Warp-level reduction for max
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        val = fmaxf(val, __shfl_xor(val, offset));
    }
    return val;
}

// Block-level reduction for max using shared memory
__device__ float block_reduce_max(float val, float* shared) {
    int lane = threadIdx.x % 64;
    int wid = threadIdx.x / 64;

    val = warp_reduce_max(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    val = (threadIdx.x < blockDim.x / 64) ? shared[lane] : -FLT_MAX;
    if (wid == 0) val = warp_reduce_max(val);

    return val;
}

// Kernel to compute amax (absolute maximum) of a tensor
__global__ void compute_amax_kernel(const float* __restrict__ input, 
                                     float* __restrict__ output,
                                     int size) {
    __shared__ float shared[16];

    float max_val = -FLT_MAX;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < size; i += stride) {
        max_val = fmaxf(max_val, fabsf(input[i]));
    }

    max_val = block_reduce_max(max_val, shared);

    if (threadIdx.x == 0) {
        atomicMax((int*)output, __float_as_int(max_val));
    }
}

// Half precision version
__global__ void compute_amax_kernel_half(const at::Half* __restrict__ input, 
                                          float* __restrict__ output,
                                          int size) {
    __shared__ float shared[16];

    float max_val = -FLT_MAX;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < size; i += stride) {
        max_val = fmaxf(max_val, fabsf(__half2float(input[i])));
    }

    max_val = block_reduce_max(max_val, shared);

    if (threadIdx.x == 0) {
        atomicMax((int*)output, __float_as_int(max_val));
    }
}

torch::Tensor compute_amax_hip(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::zeros({1}, torch::TensorOptions().dtype(torch::kFloat32).device(input.device()));

    const int block_size = 256;
    const int num_blocks = min((size + block_size - 1) / block_size, 1024);

    if (input.dtype() == torch::kFloat16) {
        compute_amax_kernel_half<<<num_blocks, block_size, 0, at::hip::getCurrentHIPStream()>>>(
            (at::Half*)input.data_ptr<at::Half>(), 
            output.data_ptr<float>(), 
            size
        );
    } else {
        compute_amax_kernel<<<num_blocks, block_size, 0, at::hip::getCurrentHIPStream()>>>(
            input.data_ptr<float>(), 
            output.data_ptr<float>(), 
            size
        );
    }

    return output;
}
"""

fp8_module = load_inline(
    name="fp8_quantize",
    cpp_sources=fp8_quantize_source,
    functions=["compute_amax_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    """
    Optimized FP8 Matrix Multiplication with pre-quantized weights.

    Optimizations:
    1. Pre-quantize weights at initialization (avoids redundant quantization each forward)
    2. Cache weight scale
    3. Use custom HIP kernel for faster amax computation
    """

    def __init__(self, M: int, K: int, N: int, use_e4m3: bool = True):
        super().__init__()
        self.M = M
        self.K = K
        self.N = N
        self.use_e4m3 = use_e4m3

        # FP8 format specifications
        if use_e4m3:
            self.fp8_dtype = torch.float8_e4m3fn
            self.fp8_max = 448.0
        else:
            self.fp8_dtype = torch.float8_e5m2
            self.fp8_max = 57344.0

        # Initialize weight in FP16
        weight_fp16 = torch.randn(K, N, dtype=torch.float16) * 0.02

        # Pre-quantize weight to FP8 and store scale
        # Weight transposed to (N, K) for _scaled_mm
        w_t = weight_fp16.t().contiguous()  # (N, K)
        w_amax = w_t.abs().max()
        w_scale = self.fp8_max / w_amax.clamp(min=1e-12)
        w_scaled = w_t * w_scale
        w_clamped = w_scaled.clamp(-self.fp8_max, self.fp8_max)

        # Store pre-quantized weight and its inverse scale
        self.register_buffer('weight_fp8', w_clamped.to(self.fp8_dtype))
        self.register_buffer('w_scale_inv', (1.0 / w_scale).to(torch.float32).unsqueeze(0))

        # Also keep FP16 weight for reference/recomputation if needed
        self.weight = nn.Parameter(weight_fp16)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Optimized FP8 matmul with pre-quantized weights.

        Input x: (batch, seq_len, K) in FP16/BF16
        Output: (batch, seq_len, N) in FP16/BF16
        """
        input_dtype = x.dtype
        batch_size = x.shape[0]
        seq_len = x.shape[1]

        # Reshape for matmul: (batch, seq, K) -> (batch*seq, K)
        x_2d = x.view(-1, self.K)

        # Compute input scale using custom kernel
        x_amax = fp8_module.compute_amax_hip(x_2d)
        x_scale = self.fp8_max / x_amax.clamp(min=1e-12)

        # Quantize input to FP8
        x_scaled = x_2d * x_scale
        x_clamped = x_scaled.clamp(-self.fp8_max, self.fp8_max)
        x_fp8 = x_clamped.to(self.fp8_dtype)

        # Inverse scale for _scaled_mm
        x_scale_inv = (1.0 / x_scale).to(torch.float32)

        # FP8 GEMM using tensor cores with pre-quantized weights
        out = torch._scaled_mm(
            x_fp8,
            self.weight_fp8.t(),
            scale_a=x_scale_inv,
            scale_b=self.w_scale_inv,
            out_dtype=input_dtype,
        )

        return out.view(batch_size, seq_len, self.N)


def custom_kernel(inputs):
    """Entry point for benchmarking."""
    x = inputs[0]
    batch_size = 8
    seq_len = 2048
    M = batch_size * seq_len
    K = 4096
    N = 4096
    use_e4m3 = True

    # Create model and move to correct device
    model = ModelNew(M, K, N, use_e4m3)
    model = model.to(x.device)
    model.eval()

    with torch.no_grad():
        return model(x)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused SiLU multiply kernel
fused_silu_mul_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_silu_mul_kernel(
    const float* __restrict__ gate,
    const float* __restrict__ up,
    float* __restrict__ out,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate[idx];
        float sigmoid_g = 1.0f / (1.0f + expf(-g));
        out[idx] = g * sigmoid_g * up[idx];
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor gate, torch::Tensor up) {
    auto size = gate.numel();
    auto out = torch::empty_like(gate);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_silu_mul_kernel<<<num_blocks, block_size>>>(
        gate.data_ptr<float>(),
        up.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

# Fused weighted sum kernel for expert outputs
fused_weighted_sum_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_weighted_sum_kernel(
    const float* __restrict__ expert_out,  // (num_tokens, top_k, hidden)
    const float* __restrict__ weights,      // (num_tokens, top_k)
    float* __restrict__ out,                // (num_tokens, hidden)
    int num_tokens,
    int top_k,
    int hidden_size
) {
    int token_idx = blockIdx.x;
    int hidden_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (token_idx < num_tokens && hidden_idx < hidden_size) {
        float sum = 0.0f;
        for (int k = 0; k < top_k; k++) {
            float w = weights[token_idx * top_k + k];
            float val = expert_out[token_idx * top_k * hidden_size + k * hidden_size + hidden_idx];
            sum += w * val;
        }
        out[token_idx * hidden_size + hidden_idx] = sum;
    }
}

torch::Tensor fused_weighted_sum_hip(torch::Tensor expert_out, torch::Tensor weights, int hidden_size) {
    int num_tokens = expert_out.size(0);
    int top_k = expert_out.size(1);

    auto out = torch::empty({num_tokens, hidden_size}, expert_out.options());

    const int block_size = 256;
    dim3 blocks(num_tokens, (hidden_size + block_size - 1) / block_size);

    fused_weighted_sum_kernel<<<blocks, block_size>>>(
        expert_out.data_ptr<float>(),
        weights.data_ptr<float>(),
        out.data_ptr<float>(),
        num_tokens,
        top_k,
        hidden_size
    );

    return out;
}
"""

cpp_source = fused_silu_mul_source + fused_weighted_sum_source

fused_ops = load_inline(
    name="fused_moe_ops",
    cpp_sources=cpp_source,
    functions=["fused_silu_mul_hip", "fused_weighted_sum_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"],
)


class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()

        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts
        self.fused_ops = fused_ops

        self.gate_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(n_routed_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        assert not self.training, "DeepSeek MoE grouped selection is inference-only"

        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape

        topk_idx, topk_weight = self.gate(hidden_states)
        hidden_states = hidden_states.view(-1, self.hidden_size)
        num_tokens = hidden_states.shape[0]

        flat_topk_idx = topk_idx.view(-1)

        expanded_tokens = hidden_states.unsqueeze(1).expand(-1, self.num_experts_per_tok, -1)
        expanded_tokens = expanded_tokens.reshape(-1, self.hidden_size)

        selected_gate = self.gate_proj[flat_topk_idx]
        selected_up = self.up_proj[flat_topk_idx]
        selected_down = self.down_proj[flat_topk_idx]

        x = expanded_tokens.unsqueeze(-1)

        gate_out = torch.bmm(selected_gate, x).squeeze(-1)
        up_out = torch.bmm(selected_up, x).squeeze(-1)

        # Use fused SiLU * multiply kernel
        intermediate = self.fused_ops.fused_silu_mul_hip(gate_out.contiguous(), up_out.contiguous())

        expert_out = torch.bmm(selected_down, intermediate.unsqueeze(-1)).squeeze(-1)

        expert_out = expert_out.view(num_tokens, self.num_experts_per_tok, self.hidden_size)

        # Use fused weighted sum kernel
        y = self.fused_ops.fused_weighted_sum_hip(
            expert_out.contiguous(), 
            topk_weight.contiguous(),
            self.hidden_size
        )

        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_gate = self.shared_gate_proj(identity)
            shared_up = self.shared_up_proj(identity)
            shared_intermediate = self.fused_ops.fused_silu_mul_hip(
                shared_gate.contiguous(), 
                shared_up.contiguous()
            )
            shared_out = self.shared_down_proj(shared_intermediate)
            y = y + shared_out

        return y


def custom_kernel(inputs):
    hidden_states = inputs[0]

    # Initialize model parameters
    hidden_size = 2048
    intermediate_size = 1408
    n_routed_experts = 64
    num_experts_per_tok = 8
    n_group = 8
    topk_group = 4
    n_shared_experts = 2
    routed_scaling_factor = 2.5

    model = ModelNew(
        hidden_size,
        intermediate_size,
        n_routed_experts,
        num_experts_per_tok,
        n_group,
        topk_group,
        n_shared_experts,
        routed_scaling_factor,
    ).cuda().eval()

    with torch.no_grad():
        return model(hidden_states)

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>

// Tile sizes for the GEMM
#define TILE_M 64
#define TILE_N 64
#define TILE_K 32
#define THREADS_PER_BLOCK 256

// Fused INT4 unpack + dequant + GEMM kernel
// X: (M, K) fp16
// weight_packed: (N, K/2) uint8
// scales: (N, num_groups) fp16
// output: (M, N) fp16
__global__ void int4_gemm_kernel(
    const __half* __restrict__ X,
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ output,
    int M, int N, int K, int group_size, int num_groups
) {
    // Each thread computes one element of output
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // N dimension

    if (row >= M || col >= N) return;

    float acc = 0.0f;

    // Loop over K dimension
    for (int k = 0; k < K; k++) {
        // Get input value
        float x_val = __half2float(X[row * K + k]);

        // Unpack INT4 weight
        // Each byte contains 2 INT4 values: low nibble = even k, high nibble = odd k
        int packed_idx = col * (K / 2) + (k / 2);
        uint8_t packed_byte = weight_packed[packed_idx];

        int w_int;
        if (k % 2 == 0) {
            w_int = packed_byte & 0x0F;  // low nibble
        } else {
            w_int = (packed_byte >> 4) & 0x0F;  // high nibble
        }

        // Get scale for this group
        int group_idx = k / group_size;
        float scale = __half2float(scales[col * num_groups + group_idx]);

        // Dequantize: scale * (w_int - 8)
        float w_dequant = scale * (float)(w_int - 8);

        acc += x_val * w_dequant;
    }

    output[row * N + col] = __float2half(acc);
}

// More optimized version with shared memory tiling
__global__ void int4_gemm_tiled_kernel(
    const __half* __restrict__ X,
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ output,
    int M, int N, int K, int group_size, int num_groups
) {
    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread indices within block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row/col this thread will compute
    int row = by * 16 + ty;
    int col = bx * 16 + tx;

    float acc = 0.0f;

    // Shared memory for input tile
    __shared__ float X_shared[16][32];

    if (row < M && col < N) {
        // Process K dimension in chunks
        for (int k_base = 0; k_base < K; k_base += 32) {
            // Load X tile into shared memory
            for (int k_off = 0; k_off < 32 && (k_base + k_off) < K; k_off += 2) {
                if (tx < 16 && (k_base + k_off + ty / 8 * 16) < K) {
                    int k_idx = k_base + k_off + (ty & 1) * 16 + tx;
                    if (k_idx < K && row < M) {
                        X_shared[ty][k_off + tx / 16 * 16 + tx % 16] = __half2float(X[row * K + k_base + k_off + tx % 16]);
                    }
                }
            }

            __syncthreads();

            // Compute partial dot product
            for (int k = 0; k < 32 && (k_base + k) < K; k++) {
                int global_k = k_base + k;

                // Get input value
                float x_val = __half2float(X[row * K + global_k]);

                // Unpack INT4 weight
                int packed_idx = col * (K / 2) + (global_k / 2);
                uint8_t packed_byte = weight_packed[packed_idx];

                int w_int;
                if (global_k % 2 == 0) {
                    w_int = packed_byte & 0x0F;
                } else {
                    w_int = (packed_byte >> 4) & 0x0F;
                }

                // Get scale
                int group_idx = global_k / group_size;
                float scale = __half2float(scales[col * num_groups + group_idx]);

                // Dequantize and accumulate
                float w_dequant = scale * (float)(w_int - 8);
                acc += x_val * w_dequant;
            }

            __syncthreads();
        }

        output[row * N + col] = __float2half(acc);
    }
}

// Simple but efficient version - process 4 K elements per iteration
__global__ void int4_gemm_vec_kernel(
    const __half* __restrict__ X,
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ output,
    int M, int N, int K, int group_size, int num_groups
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= M || col >= N) return;

    float acc = 0.0f;

    // Process 2 K elements per iteration (one packed byte)
    for (int k = 0; k < K; k += 2) {
        // Load 2 input values
        float x0 = __half2float(X[row * K + k]);
        float x1 = __half2float(X[row * K + k + 1]);

        // Load packed byte containing 2 INT4 weights
        int packed_idx = col * (K / 2) + (k / 2);
        uint8_t packed_byte = weight_packed[packed_idx];

        // Unpack both INT4 values
        int w0_int = packed_byte & 0x0F;
        int w1_int = (packed_byte >> 4) & 0x0F;

        // Get scales (may be same for both if in same group)
        int group0 = k / group_size;
        int group1 = (k + 1) / group_size;
        float scale0 = __half2float(scales[col * num_groups + group0]);
        float scale1 = __half2float(scales[col * num_groups + group1]);

        // Dequantize and accumulate
        float w0 = scale0 * (float)(w0_int - 8);
        float w1 = scale1 * (float)(w1_int - 8);

        acc += x0 * w0 + x1 * w1;
    }

    output[row * N + col] = __float2half(acc);
}

torch::Tensor int4_gemm_hip(
    torch::Tensor x,
    torch::Tensor weight_packed,
    torch::Tensor scales,
    int64_t K,
    int64_t N,
    int64_t group_size
) {
    // x: (M, K) or (batch, seq, K) -> reshape to (M, K)
    auto x_shape = x.sizes();
    int64_t M = x.numel() / K;

    auto x_2d = x.view({M, K}).contiguous();
    auto output = torch::empty({M, N}, x.options());

    int num_groups = K / group_size;

    // Launch kernel
    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    int4_gemm_vec_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(x_2d.data_ptr<at::Half>()),
        weight_packed.data_ptr<uint8_t>(),
        reinterpret_cast<const __half*>(scales.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        M, N, K, group_size, num_groups
    );

    return output;
}
"""

