import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math

os.environ["CXX"] = "hipcc"

from torch.utils.cpp_extension import load_inline

# Fused delta rule kernel using global memory for state
gated_deltanet_cpp_source = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>

// Each block handles one (batch, head) pair
// State is stored in global memory, we iterate through time
// and parallelize within each timestep across the state matrix elements

__global__ void gated_deltanet_recurrence_kernel(
    const float* __restrict__ q,      // (batch, seq, heads, d_qk)
    const float* __restrict__ k,      // (batch, seq, heads, d_qk)
    const float* __restrict__ v,      // (batch, seq, heads, d_v)
    const float* __restrict__ alpha,  // (batch, seq, heads)
    const float* __restrict__ beta,   // (batch, seq, heads)
    float* __restrict__ state,        // (batch, heads, d_v, d_qk) - workspace
    float* __restrict__ output,       // (batch, seq, heads, d_v)
    int batch_size,
    int seq_len,
    int num_heads,
    int d_qk,
    int d_v
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    // Shared memory for k, v, S_k, q vectors
    extern __shared__ float shared_mem[];
    float* k_shared = shared_mem;        // d_qk
    float* v_shared = k_shared + d_qk;   // d_v
    float* S_k = v_shared + d_v;         // d_v
    float* q_shared = S_k + d_v;         // d_qk

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // State base pointer for this (batch, head)
    int state_base = (batch_idx * num_heads + head_idx) * d_v * d_qk;
    float* S = state + state_base;

    // Initialize state to zero
    for (int i = tid; i < d_v * d_qk; i += block_size) {
        S[i] = 0.0f;
    }
    __syncthreads();

    // Process each timestep
    for (int t = 0; t < seq_len; t++) {
        int qkv_base = ((batch_idx * seq_len + t) * num_heads + head_idx);
        int alpha_beta_idx = (batch_idx * seq_len + t) * num_heads + head_idx;

        // Load k and v
        for (int i = tid; i < d_qk; i += block_size) {
            k_shared[i] = k[qkv_base * d_qk + i];
        }
        for (int i = tid; i < d_v; i += block_size) {
            v_shared[i] = v[qkv_base * d_v + i];
        }
        __syncthreads();

        float alpha_t = alpha[alpha_beta_idx];
        float beta_t = beta[alpha_beta_idx];

        // Compute S @ k -> S_k
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            for (int j = 0; j < d_qk; j++) {
                sum += S[i * d_qk + j] * k_shared[j];
            }
            S_k[i] = sum;
        }
        __syncthreads();

        // Update state: S = alpha * S - beta * (S_k - v) @ k^T
        for (int idx = tid; idx < d_v * d_qk; idx += block_size) {
            int i = idx / d_qk;
            int j = idx % d_qk;
            float error_i = S_k[i] - v_shared[i];
            S[idx] = alpha_t * S[idx] - beta_t * error_i * k_shared[j];
        }
        __syncthreads();

        // Load q
        for (int i = tid; i < d_qk; i += block_size) {
            q_shared[i] = q[qkv_base * d_qk + i];
        }
        __syncthreads();

        // Compute output: o = S @ q
        int out_base = qkv_base * d_v;
        for (int i = tid; i < d_v; i += block_size) {
            float sum = 0.0f;
            for (int j = 0; j < d_qk; j++) {
                sum += S[i * d_qk + j] * q_shared[j];
            }
            output[out_base + i] = sum;
        }
        __syncthreads();
    }
}

torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
) {
    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int d_qk = q.size(3);
    int d_v = v.size(3);

    auto output = torch::zeros({batch_size, seq_len, num_heads, d_v}, q.options());

    // Workspace for state matrices
    auto state = torch::zeros({batch_size, num_heads, d_v, d_qk}, q.options());

    dim3 grid(batch_size, num_heads);
    int block_size = 256;

    // Shared memory: k[d_qk] + v[d_v] + S_k[d_v] + q[d_qk]
    size_t shared_mem_size = (2 * d_qk + 2 * d_v) * sizeof(float);

    gated_deltanet_recurrence_kernel<<<grid, block_size, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        alpha.data_ptr<float>(),
        beta.data_ptr<float>(),
        state.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        seq_len,
        num_heads,
        d_qk,
        d_v
    );

    return output;
}
"""

gated_deltanet_cpp_header = """
torch::Tensor gated_deltanet_recurrence(
    torch::Tensor q,
    torch::Tensor k,
    torch::Tensor v,
    torch::Tensor alpha,
    torch::Tensor beta
);
"""

