import os
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Improved fused HIP kernel for Kimi Delta Attention recurrence
# Optimizations:
# 1. Better thread utilization with 2D thread blocks
# 2. Vectorized memory loads where possible
# 3. Loop unrolling for inner loops
# 4. Reduced shared memory bank conflicts

kda_hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define WARP_SIZE 64
#define BLOCK_DIM_X 64
#define BLOCK_DIM_Y 4

// Optimized kernel with better parallelism
// Uses 2D thread blocks: X dimension for dk/dv, Y dimension for parallel work
__global__ void kda_recurrence_kernel_v2(
    const float* __restrict__ q,      // (batch, seq, heads, dk)
    const float* __restrict__ k,      // (batch, seq, heads, dk)
    const float* __restrict__ v,      // (batch, seq, heads, dv)
    const float* __restrict__ a,      // (batch, seq, heads, dv) - channel gates
    const float* __restrict__ beta,   // (batch, seq, heads)
    float* __restrict__ output,       // (batch, seq, heads, dv)
    float* __restrict__ S,            // (batch, heads, dv, dk) - state buffer
    int batch_size,
    int seq_len,
    int num_heads,
    int head_dim_qk,
    int head_dim_v
) {
    // Each block handles one (batch, head) pair
    int bh_idx = blockIdx.x;
    int b = bh_idx / num_heads;
    int h = bh_idx % num_heads;

    if (b >= batch_size) return;

    int tid = threadIdx.x + threadIdx.y * blockDim.x;
    int total_threads = blockDim.x * blockDim.y;

    int dv = head_dim_v;
    int dk = head_dim_qk;

    // State offset for this (batch, head)
    int s_offset = (b * num_heads + h) * dv * dk;

    // Shared memory layout
    extern __shared__ float shared_mem[];
    float* s_k = shared_mem;                    // dk
    float* s_v = s_k + dk;                      // dv
    float* s_q = s_v + dv;                      // dk
    float* s_a = s_q + dk;                      // dv
    float* s_Sk = s_a + dv;                     // dv (S @ k result)

    // Process each timestep
    for (int t = 0; t < seq_len; t++) {
        // Input offsets
        int qk_offset = ((b * seq_len + t) * num_heads + h) * dk;
        int v_offset = ((b * seq_len + t) * num_heads + h) * dv;
        int beta_offset = (b * seq_len + t) * num_heads + h;

        // Cooperative load of k, v, q, a with coalesced access
        for (int i = tid; i < dk; i += total_threads) {
            s_k[i] = k[qk_offset + i];
            s_q[i] = q[qk_offset + i];
        }
        for (int i = tid; i < dv; i += total_threads) {
            s_v[i] = v[v_offset + i];
            s_a[i] = a[v_offset + i];
        }
        __syncthreads();

        float beta_t = beta[beta_offset];

        // Compute S @ k -> s_Sk (each thread handles multiple rows)
        // Unroll by 4 for better performance
        for (int i = tid; i < dv; i += total_threads) {
            float sum = 0.0f;
            int row_offset = s_offset + i * dk;

            // Unroll inner loop by 4
            int j = 0;
            for (; j + 3 < dk; j += 4) {
                sum += S[row_offset + j] * s_k[j];
                sum += S[row_offset + j + 1] * s_k[j + 1];
                sum += S[row_offset + j + 2] * s_k[j + 2];
                sum += S[row_offset + j + 3] * s_k[j + 3];
            }
            for (; j < dk; j++) {
                sum += S[row_offset + j] * s_k[j];
            }
            s_Sk[i] = sum;
        }
        __syncthreads();

        // Update S: S = diag(a) @ S - beta * (S@k - v) @ k^T
        // Each thread handles multiple elements, fusing error computation
        for (int i = tid; i < dv * dk; i += total_threads) {
            int row = i / dk;
            int col = i % dk;
            float s_old = S[s_offset + i];
            float error_row = s_Sk[row] - s_v[row];
            // Fused update: apply gate and delta correction
            S[s_offset + i] = s_a[row] * s_old - beta_t * error_row * s_k[col];
        }
        __syncthreads();

        // Compute output: o = S @ q with unrolling
        for (int i = tid; i < dv; i += total_threads) {
            float sum = 0.0f;
            int row_offset = s_offset + i * dk;

            int j = 0;
            for (; j + 3 < dk; j += 4) {
                sum += S[row_offset + j] * s_q[j];
                sum += S[row_offset + j + 1] * s_q[j + 1];
                sum += S[row_offset + j + 2] * s_q[j + 2];
                sum += S[row_offset + j + 3] * s_q[j + 3];
            }
            for (; j < dk; j++) {
                sum += S[row_offset + j] * s_q[j];
            }
            output[v_offset + i] = sum;
        }
        __syncthreads();
    }
}

torch::Tensor kda_forward_hip(
    torch::Tensor q,      // (batch, seq, heads, dk)
    torch::Tensor k,      // (batch, seq, heads, dk)
    torch::Tensor v,      // (batch, seq, heads, dv)
    torch::Tensor a,      // (batch, seq, heads, dv)
    torch::Tensor beta    // (batch, seq, heads)
) {
    int batch_size = q.size(0);
    int seq_len = q.size(1);
    int num_heads = q.size(2);
    int head_dim_qk = q.size(3);
    int head_dim_v = v.size(3);

    auto options = torch::TensorOptions().dtype(q.dtype()).device(q.device());

    // Output tensor
    auto output = torch::zeros({batch_size, seq_len, num_heads, head_dim_v}, options);

    // State tensor (initialized to zeros)
    auto S = torch::zeros({batch_size, num_heads, head_dim_v, head_dim_qk}, options);

    // Launch configuration - 256 threads per block
    int num_blocks = batch_size * num_heads;
    dim3 threads(64, 4);  // 256 threads in 2D configuration

    // Shared memory: k(dk) + v(dv) + q(dk) + a(dv) + Sk(dv)
    size_t shared_mem_size = (head_dim_qk * 2 + head_dim_v * 3) * sizeof(float);

    hipLaunchKernelGGL(kda_recurrence_kernel_v2, 
        dim3(num_blocks), threads, shared_mem_size, 0,
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        a.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        S.data_ptr<float>(),
        batch_size, seq_len, num_heads, head_dim_qk, head_dim_v
    );

    return output;
}
