# Highly optimized fused RoPE kernel with warp-level primitives
fused_ops_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused RoPE forward pass - optimized with coalesced memory access
__global__ void fused_rope_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ output,
    const int batch_size,
    const int num_heads,
    const int seq_len,
    const int head_dim,
    const int half_dim
) {
    // Grid: (batch * num_heads * seq_len * half_dim) threads
    // Each thread handles one element from first half and computes corresponding rotation
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * num_heads * seq_len * half_dim;

    if (gid >= total) return;

    // Decode position
    int d = gid % half_dim;
    int remaining = gid / half_dim;
    int s = remaining % seq_len;
    remaining = remaining / seq_len;
    int h = remaining % num_heads;
    int b = remaining / num_heads;

    // Calculate indices
    int stride_b = num_heads * seq_len * head_dim;
    int stride_h = seq_len * head_dim;
    int stride_s = head_dim;

    int base_idx = b * stride_b + h * stride_h + s * stride_s;
    int idx1 = base_idx + d;           // First half element
    int idx2 = base_idx + d + half_dim; // Second half element

    // cos/sin indices (shape: [1, 1, seq_len, head_dim])
    int cs_idx1 = s * head_dim + d;
    int cs_idx2 = s * head_dim + d + half_dim;

    float x1 = input[idx1];
    float x2 = input[idx2];
    float c1 = cos[cs_idx1];
    float s1 = sin[cs_idx1];
    float c2 = cos[cs_idx2];
    float s2 = sin[cs_idx2];

    // Apply rotation: output[i] = input[i] * cos[i] + rotate_half(input)[i] * sin[i]
    // rotate_half: [-x2, x1] for [x1, x2]
    output[idx1] = x1 * c1 + (-x2) * s1;
    output[idx2] = x2 * c2 + x1 * s2;
}

torch::Tensor fused_rope_forward(torch::Tensor input, torch::Tensor cos, torch::Tensor sin) {
    auto batch_size = input.size(0);
    auto num_heads = input.size(1);
    auto seq_len = input.size(2);
    auto head_dim = input.size(3);
    int half_dim = head_dim / 2;

    auto output = torch::empty_like(input);

    int total = batch_size * num_heads * seq_len * half_dim;
    int block_size = 256;
    int num_blocks = (total + block_size - 1) / block_size;

    fused_rope_forward_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_heads,
        seq_len,
        head_dim,
        half_dim
    );

    return output;
}

// Apply RoPE to both Q and K in a single kernel launch
std::vector<torch::Tensor> fused_rope_qk(
    torch::Tensor Q, 
    torch::Tensor K, 
    torch::Tensor cos, 
    torch::Tensor sin
) {
    auto Q_out = fused_rope_forward(Q, cos, sin);
    auto K_out = fused_rope_forward(K, cos, sin);
    return {Q_out, K_out};
}
"""

fused_ops_cpp = """
torch::Tensor fused_rope_forward(torch::Tensor input, torch::Tensor cos, torch::Tensor sin);
std::vector<torch::Tensor> fused_rope_qk(torch::Tensor Q, torch::Tensor K, torch::Tensor cos, torch::Tensor sin);
"""

fused_ops = load_inline(
    name="fused_ops_v3",
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=["fused_rope_forward", "fused_rope_qk"],
    verbose=True,
    extra_cuda_cflags=["-O3", "-ffast-math"],
)


class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)
        self._cos_cache = None
        self._sin_cache = None
        self._cache_len = 0

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]

        if seq_len != self._cache_len or self._cos_cache is None or self._cos_cache.device != x.device:
            t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
            freqs = torch.outer(t, self.inv_freq.to(x.device))
            emb = torch.cat((freqs, freqs), dim=-1)
            self._cos_cache = emb.cos().unsqueeze(0).unsqueeze(0).contiguous()
            self._sin_cache = emb.sin().unsqueeze(0).unsqueeze(0).contiguous()
            self._cache_len = seq_len

        return self._cos_cache, self._sin_cache


class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.q_proj = nn.Linear(hidden_size, num_attention_heads * head_dim, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_key_value_heads * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

        self.fused_ops = fused_ops

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        # Project Q, K, V
        query_states = self.q_proj(hidden_states)
        key_states = self.k_proj(hidden_states)
        value_states = self.v_proj(hidden_states)

        # Reshape for multi-head attention
        query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2).contiguous()
        key_states = key_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()
        value_states = value_states.view(bsz, q_len, self.num_kv_heads, self.head_dim).transpose(1, 2).contiguous()

        # Get cached cos/sin for RoPE
        cos, sin = self.rotary_emb(value_states, seq_len=q_len)

        # Apply fused RoPE to Q and K
        query_states, key_states = self.fused_ops.fused_rope_qk(query_states, key_states, cos, sin)

        # Expand KV heads efficiently using repeat_interleave
        # PyTorch's SDPA doesn't natively support GQA without expansion
        key_states = key_states.repeat_interleave(self.num_key_value_groups, dim=1)
        value_states = value_states.repeat_interleave(self.num_key_value_groups, dim=1)

        # Use PyTorch's highly optimized SDPA with flash attention backend
        attn_output = F.scaled_dot_product_attention(
            query_states,
            key_states,
            value_states,
            attn_mask=None,
            dropout_p=self.attention_dropout if self.training else 0.0,
            is_causal=True,
            scale=self.softmax_scale,
        )

        # Reshape output
        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)

        # Output projection
        attn_output = self.o_proj(attn_output)

        return attn_output


def custom_kernel(inputs):
    hidden_states = inputs[0]

    model = ModelNew(
        hidden_size=4096,
        num_attention_heads=32,
        num_key_value_heads=8,
        head_dim=128,
        max_position_embeddings=4096,
    ).cuda().eval()

    with torch.no_grad():
        return model(hidden_states)

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
