# Optimized RMSNorm kernel - ensure high precision
rmsnorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void rmsnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int hidden_size,
    float eps,
    int total_tokens
) {
    int token_idx = blockIdx.x;
    if (token_idx >= total_tokens) return;

    const float* token_input = input + (long long)token_idx * hidden_size;
    float* token_output = output + (long long)token_idx * hidden_size;

    // Use double precision for variance computation
    double sum_sq = 0.0;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        double val = (double)token_input[i];
        sum_sq += val * val;
    }

    // Warp reduction
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        sum_sq += __shfl_down(sum_sq, offset);
    }

    // Block reduction
    __shared__ double shared_sum[8];
    int lane = threadIdx.x % 64;
    int warp_id = threadIdx.x / 64;

    if (lane == 0) {
        shared_sum[warp_id] = sum_sq;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        double total = 0.0;
        int num_warps = (blockDim.x + 63) / 64;
        for (int i = 0; i < num_warps; i++) {
            total += shared_sum[i];
        }
        shared_sum[0] = rsqrt(total / hidden_size + (double)eps);
    }
    __syncthreads();

    float rsqrt_var = (float)shared_sum[0];

    // Apply normalization
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        output[i] = token_input[i] * rsqrt_var * weight[i];
    }
}

torch::Tensor rmsnorm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    auto output = torch::empty_like(input);

    int hidden_size = input.size(-1);
    int total_tokens = input.numel() / hidden_size;

    int block_size = 256;

    rmsnorm_kernel<<<total_tokens, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        hidden_size,
        eps,
        total_tokens
    );

    return output;
}
"""

