os.environ["CXX"] = "hipcc"

hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>

// Fused INT4 unpack + dequant + GEMM kernel
// X: (M, K) fp16
// weight_packed: (N, K/2) uint8
// scales: (N, num_groups) fp16
// output: (M, N) fp16
__global__ void int4_gemm_kernel(
    const __half* __restrict__ X,
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ output,
    int M, int N, int K, int group_size, int num_groups
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // N dimension

    if (row >= M || col >= N) return;

    float acc = 0.0f;

    // Process 2 K elements per iteration (one packed byte)
    int K_half = K / 2;
    for (int k2 = 0; k2 < K_half; k2++) {
        int k = k2 * 2;  // actual k index for first element

        // Load 2 input values
        float x0 = __half2float(X[row * K + k]);
        float x1 = __half2float(X[row * K + k + 1]);

        // Load packed byte containing 2 INT4 weights
        uint8_t packed_byte = weight_packed[col * K_half + k2];

        // Unpack: low nibble = first weight (k), high nibble = second weight (k+1)
        int w0_int = packed_byte & 0x0F;
        int w1_int = (packed_byte >> 4) & 0x0F;

        // Get scales for both weights
        int group0 = k / group_size;
        int group1 = (k + 1) / group_size;
        float scale0 = __half2float(scales[col * num_groups + group0]);
        float scale1 = __half2float(scales[col * num_groups + group1]);

        // Dequantize: scale * (w_int - 8)
        float w0 = scale0 * (float)(w0_int - 8);
        float w1 = scale1 * (float)(w1_int - 8);

        acc += x0 * w0 + x1 * w1;
    }

    output[row * N + col] = __float2half(acc);
}

torch::Tensor int4_gemm_hip(
    torch::Tensor x,
    torch::Tensor weight_packed,
    torch::Tensor scales,
    int64_t K,
    int64_t N,
    int64_t group_size
) {
    // x: (batch, seq, K) -> reshape to (M, K)
    int64_t M = x.numel() / K;

    auto x_2d = x.view({M, K}).contiguous();
    auto output = torch::empty({M, N}, x.options());

    int num_groups = K / group_size;

    // Launch kernel
    dim3 block(16, 16);
    dim3 grid((N + 15) / 16, (M + 15) / 16);

    int4_gemm_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(x_2d.data_ptr<at::Half>()),
        weight_packed.data_ptr<uint8_t>(),
        reinterpret_cast<const __half*>(scales.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        M, N, K, group_size, num_groups
    );

    return output;
}
"""

cpp_source = """
