# Optimized fused RoPE kernel
fused_ops_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Vectorized RoPE kernel - processes 2 elements per thread
__global__ void rope_kernel_v2(
    const float* __restrict__ input,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ output,
    const int batch_heads,
    const int seq_len,
    const int head_dim,
    const int half_dim
) {
    // Each thread processes one pair (first half element and corresponding second half element)
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_heads * seq_len * half_dim;

    if (gid >= total) return;

    // Decode position
    int d = gid % half_dim;
    int remaining = gid / half_dim;
    int s = remaining % seq_len;
    int bh = remaining / seq_len;

    int stride = seq_len * head_dim;
    int base_idx = bh * stride + s * head_dim;
    int idx1 = base_idx + d;
    int idx2 = base_idx + d + half_dim;

    int cs_idx1 = s * head_dim + d;
    int cs_idx2 = s * head_dim + d + half_dim;

    // Load input pair
    float x1 = input[idx1];
    float x2 = input[idx2];

    // Load cos/sin
    float c1 = cos[cs_idx1];
    float s1 = sin[cs_idx1];
    float c2 = cos[cs_idx2];
    float s2 = sin[cs_idx2];

    // Rotary embedding: rotate_half produces [-x2, x1]
    // So: out[d] = x1 * cos[d] + (-x2) * sin[d]
    //     out[d+half] = x2 * cos[d+half] + x1 * sin[d+half]
    output[idx1] = x1 * c1 - x2 * s1;
    output[idx2] = x2 * c2 + x1 * s2;
}

torch::Tensor rope_forward(torch::Tensor input, torch::Tensor cos, torch::Tensor sin) {
    auto batch_size = input.size(0);
    auto num_heads = input.size(1);
    auto seq_len = input.size(2);
    auto head_dim = input.size(3);
    int half_dim = head_dim / 2;

    auto output = torch::empty_like(input);

    int batch_heads = batch_size * num_heads;
    int total = batch_heads * seq_len * half_dim;
    int block_size = 256;
    int num_blocks = (total + block_size - 1) / block_size;

    rope_kernel_v2<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_heads,
        seq_len,
        head_dim,
        half_dim
    );

    return output;
}
"""

fused_ops_cpp = """
torch::Tensor rope_forward(torch::Tensor input, torch::Tensor cos, torch::Tensor sin);
"""

fused_ops = load_inline(
    name="fused_ops_v6",
